/** A verified device assertion can approve once; cancellation never authorises. */
export function openBiometricAuth(ctx,{onSuccess,onFallback,onCancel,title='A quick check. Then you’re good.',deviceAuth={authenticateDevice}}={}){
  const bio=ensureAccountState(ctx.state).biometrics;
  if(!bio?.credential||!bio.paymentsEnabled)return false;
  let done=false,busy=false,controller=null;
  const initiatingRoute=JSON.stringify(ctx.route||null),credentialId=bio.credential.id;
  const validContext=()=>accountAccess(ctx.state).canTransact&&JSON.stringify(ctx.route||null)===initiatingRoute&&ensureAccountState(ctx.state).biometrics?.credential?.id===credentialId&&ensureAccountState(ctx.state).biometrics.paymentsEnabled;
  ctx.sheet(`<div class="account-biometric auth-device-sheet"><span class="account-icon">${icon('scan',36)}</span><h2>${esc(title)}</h2><p>Approve with your phone’s face, fingerprint or screen lock.</p><p class="error" data-biometric-error role="alert"></p><button class="button" data-biometric-verify>Verify with my phone</button><button class="button secondary" data-biometric-pin>Use transaction PIN</button><p class="auth-demo-note">Your phone handles verification. Lumo does not see your face or fingerprint.</p></div>`,el=>{
    const verify=el.querySelector('[data-biometric-verify]');
    verify.onclick=async()=>{
      if(done||busy)return;busy=true;verify.disabled=true;controller=new AbortController();el.querySelector('[data-biometric-error]').textContent='';
      try{const result=await deviceAuth.authenticateDevice(bio.credential,{purpose:'transaction',signal:controller.signal});if(done||controller.signal.aborted||el.isConnected===false||!validContext())return;
        if(!result.ok){el.querySelector('[data-biometric-error]').textContent=result.message||'Verification did not finish. Try again or use your transaction PIN.';return;}
        const confirmed=ctx.act('accountBiometricVerified',{proof:result.proof});if(!confirmed.ok){el.querySelector('[data-biometric-error]').textContent=confirmed.message;return;}
        done=true;ctx.closeSheet();onSuccess?.();
      }catch{if(!done&&el.isConnected!==false)el.querySelector('[data-biometric-error]').textContent='Phone verification is unavailable. Use your transaction PIN.';}
      finally{busy=false;if(!done&&el.isConnected!==false)verify.disabled=false;}
    };
    el.querySelector('[data-biometric-pin]').onclick=()=>{if(done)return;done=true;controller?.abort();ctx.closeSheet();onFallback?.();};
  },{onClose:()=>{if(done)return;done=true;controller?.abort();onCancel?.();},closeLabel:'Cancel authorisation'});
  return true;
}
